<script nonce="<?= esc_attr($nonce) ?>">
document.querySelectorAll('[data-percent]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('percent').value=button.dataset.percent;}));
document.getElementById('generate')?.addEventListener('click',()=>{const bytes=crypto.getRandomValues(new Uint8Array(6));document.getElementById('code').value='PATH-'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();});
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText(button.dataset.copy);status.textContent='Copied — ready to paste into a message.';}catch{status.textContent='Copy is unavailable in this browser. Press and hold the code to copy it.';}}));
document.getElementById('create-form')?.addEventListener('submit',event=>{if(Number(document.getElementById('percent').value)===100&&!confirm('Create a 100% discount code? This makes the booking free.')){event.preventDefault();return;}const button=event.target.querySelector('[type=submit]');button.disabled=true;button.textContent='Creating your code…';});
<?php require __DIR__ . '/portal-passkeys.js'; ?>
</script></body></html>
